package store

import (
	"context"
	"database/sql"
	"errors"
	"testing"
	"time"

	"github.com/mellifera/mellifera/internal/access"
)

// TestLedgerReadsViewerScoped pins 5.2's ledger-READ contract (l6-accounts
// D7, the ledger-read scoping law of ledgerSlotWhere): a USER-scope viewer's
// reads surface ONLY (v.UserID, visible-library) rows — the own-slot conjunct
// (user B's row on the same shared item never leaks into A's window) AND the
// visibility conjunct (a row whose item sits in a no-longer-granted library
// never leaks existence — the revoked-grant case; own slot alone is not
// enough, proven by the empty-grant user) — while the SEE-ALL viewers
// (System/Admin/LegacyDevice) keep the pre-5.2 all-slot, all-library read:
// their UserID-0 legacy slot stays byte-identical (the runtime-legacy law).
//
// Rows land through the 5.1 write paths (PutProgress/InsertWatched with the
// per-user viewers) except the revoked-grant rows, which only direct SQL can
// produce (a write whose grant was later revoked — the store's write paths
// refuse hidden items).
func TestLedgerReadsViewerScoped(t *testing.T) {
	s := openStore(t)
	ctx := context.Background()
	seed := seedViewerWorld(t, s)
	grantedID, hiddenID := "Show.A/ep1.mkv", "Show.B/ep1.mkv"
	vA := access.User(1, []int64{seed.libA}, nil)
	vB := access.User(2, []int64{seed.libA}, nil)

	// Progress: A and B each hold an independent row on the SAME granted item
	// (the 5.1 write contract); A additionally holds a revoked-grant row on
	// the now-hidden library.
	if _, err := s.PutProgress(ctx, grantedID, 60, vA); err != nil {
		t.Fatalf("PutProgress(user A): %v", err)
	}
	if _, err := s.PutProgress(ctx, grantedID, 90, vB); err != nil {
		t.Fatalf("PutProgress(user B): %v", err)
	}
	if _, err := s.db.ExecContext(ctx,
		"INSERT INTO playback_progress (user_id, item_id, position_seconds, updated_at) VALUES (1, ?, 40, ?)",
		hiddenID, "2026-02-01T00:00:00Z"); err != nil {
		t.Fatalf("seed revoked-grant progress row: %v", err)
	}

	// Watched: A and B each completed the SAME granted item; A additionally
	// holds a revoked-grant watched row in the hidden library (stamped oldest,
	// so the see-all ordering assertion below is deterministic).
	t0 := time.Date(2026, 11, 1, 12, 0, 0, 0, time.UTC)
	t1 := time.Date(2026, 11, 2, 12, 0, 0, 0, time.UTC)
	tOld := time.Date(2026, 10, 1, 0, 0, 0, 0, time.UTC)
	if err := s.InsertWatched(ctx, grantedID, seed.libA, "", t0, vA); err != nil {
		t.Fatalf("InsertWatched(user A): %v", err)
	}
	if err := s.InsertWatched(ctx, grantedID, seed.libA, "", t1, vB); err != nil {
		t.Fatalf("InsertWatched(user B): %v", err)
	}
	if _, err := s.db.ExecContext(ctx,
		"INSERT INTO watched_items (user_id, item_id, library_id, series_relative_path, completed_at) VALUES (1, ?, ?, NULL, ?)",
		hiddenID, seed.libB, formatTime(tOld)); err != nil {
		t.Fatalf("seed revoked-grant watched row: %v", err)
	}

	t.Run("progress_own_slot", func(t *testing.T) {
		// Each viewer reads ITS OWN row on the shared item — never the other's.
		gotA, err := s.GetProgress(ctx, grantedID, vA)
		if err != nil {
			t.Fatalf("GetProgress(A): %v", err)
		}
		if gotA.PositionSeconds != 60 {
			t.Fatalf("GetProgress(A) = %d, want 60 (A's own row)", gotA.PositionSeconds)
		}
		gotB, err := s.GetProgress(ctx, grantedID, vB)
		if err != nil {
			t.Fatalf("GetProgress(B): %v", err)
		}
		if gotB.PositionSeconds != 90 {
			t.Fatalf("GetProgress(B) = %d, want 90 (B's own row — A's invisible)", gotB.PositionSeconds)
		}
		// The list window holds exactly one row per viewer: own slot AND
		// granted library.
		listA, err := s.ListProgress(ctx, 10, vA)
		if err != nil {
			t.Fatalf("ListProgress(A): %v", err)
		}
		if len(listA) != 1 || listA[0].ItemID != grantedID || listA[0].PositionSeconds != 60 {
			t.Fatalf("ListProgress(A) = %+v, want exactly A's own granted row", listA)
		}
		listB, err := s.ListProgress(ctx, 10, vB)
		if err != nil {
			t.Fatalf("ListProgress(B): %v", err)
		}
		if len(listB) != 1 || listB[0].ItemID != grantedID || listB[0].PositionSeconds != 90 {
			t.Fatalf("ListProgress(B) = %+v, want exactly B's own granted row (no slot bleed)", listB)
		}
		allA, err := s.ListProgressAll(ctx, vA)
		if err != nil {
			t.Fatalf("ListProgressAll(A): %v", err)
		}
		if len(allA) != 1 || allA[0].PositionSeconds != 60 {
			t.Fatalf("ListProgressAll(A) = %+v, want exactly A's own granted row", allA)
		}
	})

	t.Run("progress_revoked_grant_never_leaks", func(t *testing.T) {
		// A's row on the now-hidden library reads as absent to A — the row
		// exists (System sees it below), its EXISTENCE never leaks.
		if _, err := s.GetProgress(ctx, hiddenID, vA); !errors.Is(err, sql.ErrNoRows) {
			t.Fatalf("GetProgress(revoked grant) = %v, want wrapped sql.ErrNoRows", err)
		}
		all, err := s.ListProgressAll(ctx, access.System())
		if err != nil {
			t.Fatalf("ListProgressAll(system): %v", err)
		}
		if len(all) != 3 {
			t.Fatalf("ListProgressAll(system) = %d rows, want 3 (A's + B's granted rows + A's revoked-grant row — the row exists)", len(all))
		}
	})

	t.Run("progress_empty_grant_and_zero_fail_closed", func(t *testing.T) {
		for name, v := range map[string]access.Viewer{
			"empty_grant_user": access.User(1, nil, nil), // same slot-1 rows exist
			"zero_viewer":      {},
		} {
			got, err := s.ListProgress(ctx, 10, v)
			if err != nil {
				t.Fatalf("ListProgress(%s): %v", name, err)
			}
			if got == nil || len(got) != 0 {
				t.Fatalf("ListProgress(%s) = %#v, want non-nil empty", name, got)
			}
			all, err := s.ListProgressAll(ctx, v)
			if err != nil {
				t.Fatalf("ListProgressAll(%s): %v", name, err)
			}
			if all == nil || len(all) != 0 {
				t.Fatalf("ListProgressAll(%s) = %#v, want non-nil empty", name, all)
			}
			if _, err := s.GetProgress(ctx, grantedID, v); !errors.Is(err, sql.ErrNoRows) {
				t.Fatalf("GetProgress(%s) = %v, want wrapped sql.ErrNoRows (own slot alone is not enough)", name, err)
			}
		}
	})

	t.Run("watched_own_slot", func(t *testing.T) {
		gotA, err := s.ListWatched(ctx, vA)
		if err != nil {
			t.Fatalf("ListWatched(A): %v", err)
		}
		if len(gotA) != 1 || gotA[0] != grantedID {
			t.Fatalf("ListWatched(A) = %v, want exactly [%s] (A's own row — B's invisible)", gotA, grantedID)
		}
		gotB, err := s.ListWatched(ctx, vB)
		if err != nil {
			t.Fatalf("ListWatched(B): %v", err)
		}
		if len(gotB) != 1 || gotB[0] != grantedID {
			t.Fatalf("ListWatched(B) = %v, want exactly [%s] (B's own row)", gotB, grantedID)
		}
	})

	t.Run("watched_revoked_grant_never_leaks", func(t *testing.T) {
		// A's watched row in the hidden library stays invisible to A — the
		// existence of the revocation never surfaces through the ledger.
		gotA, err := s.ListWatched(ctx, vA)
		if err != nil {
			t.Fatalf("ListWatched(A): %v", err)
		}
		if len(gotA) != 1 || gotA[0] != grantedID {
			t.Fatalf("ListWatched(A) = %v, want exactly [%s] (no revoked-grant leak)", gotA, grantedID)
		}
	})

	t.Run("watched_empty_grant_and_zero_fail_closed", func(t *testing.T) {
		for name, v := range map[string]access.Viewer{
			"empty_grant_user": access.User(1, nil, nil),
			"zero_viewer":      {},
		} {
			got, err := s.ListWatched(ctx, v)
			if err != nil {
				t.Fatalf("ListWatched(%s): %v", name, err)
			}
			if got == nil || len(got) != 0 {
				t.Fatalf("ListWatched(%s) = %#v, want non-nil empty", name, got)
			}
		}
	})

	t.Run("see_all_viewers_read_all_slots", func(t *testing.T) {
		for name, v := range map[string]access.Viewer{
			"system": access.System(), "admin": access.Admin(), "legacy": access.LegacyDevice(),
		} {
			all, err := s.ListProgressAll(ctx, v)
			if err != nil {
				t.Fatalf("ListProgressAll(%s): %v", name, err)
			}
			if len(all) != 3 {
				t.Fatalf("ListProgressAll(%s) = %d rows, want 3 (every slot, every library)", name, len(all))
			}
			window, err := s.ListProgress(ctx, 10, v)
			if err != nil {
				t.Fatalf("ListProgress(%s): %v", name, err)
			}
			if len(window) != 3 {
				t.Fatalf("ListProgress(%s) = %d rows, want 3 (the all-slot window)", name, len(window))
			}
			watched, err := s.ListWatched(ctx, v)
			if err != nil {
				t.Fatalf("ListWatched(%s): %v", name, err)
			}
			// Three ROWS — the shared item appears once per slot (A's and B's);
			// set-folders downstream (watchedSet) absorb the duplicate, the
			// pre-5.2 ambiguity System callers already tolerate.
			if len(watched) != 3 {
				t.Fatalf("ListWatched(%s) = %v, want 3 rows (A's + B's + the revoked-grant row)", name, watched)
			}
			if watched[0] != hiddenID || watched[1] != grantedID || watched[2] != grantedID {
				t.Fatalf("ListWatched(%s) = %v, want [%s %s %s] (completed_at order across slots)", name, watched, hiddenID, grantedID, grantedID)
			}
		}
	})
}

// TestLedgerLearningStaysSystem pins the learning invariant (l6-accounts D7,
// 5.2): ListUnappliedWatched and ApplyTagWeights carry NO viewer — the recs
// tag-learning reads and stamps are GLOBAL by design, spanning every user's
// ledger slot and every library, so the janitor's learning loop sees each
// user's completions exactly once regardless of who completed them. A
// per-user (own-slot) view here would strand every other user's watches
// unlearned forever.
func TestLedgerLearningStaysSystem(t *testing.T) {
	s := openStore(t)
	ctx := context.Background()
	seed := seedViewerWorld(t, s)
	grantedID, hiddenID := "Show.A/ep1.mkv", "Show.B/ep1.mkv"
	vA := access.User(1, []int64{seed.libA}, nil)
	vB := access.User(2, []int64{seed.libB}, nil)

	t0 := time.Date(2026, 11, 1, 12, 0, 0, 0, time.UTC)
	t1 := time.Date(2026, 11, 2, 12, 0, 0, 0, time.UTC)
	// Two users' completions in two slots AND two libraries (B's row sits in
	// the library A cannot see — learning reads it anyway).
	if err := s.InsertWatched(ctx, grantedID, seed.libA, "", t0, vA); err != nil {
		t.Fatalf("InsertWatched(user A): %v", err)
	}
	if err := s.InsertWatched(ctx, hiddenID, seed.libB, "", t1, vB); err != nil {
		t.Fatalf("InsertWatched(user B): %v", err)
	}

	itemIDs, libraryIDs, _, _, err := s.ListUnappliedWatched(ctx)
	if err != nil {
		t.Fatalf("ListUnappliedWatched: %v", err)
	}
	if len(itemIDs) != 2 || itemIDs[0] != grantedID || itemIDs[1] != hiddenID {
		t.Fatalf("unapplied queue = %v, want both users' rows [%s %s] (learning is global)", itemIDs, grantedID, hiddenID)
	}
	if len(libraryIDs) != 2 || libraryIDs[0] != seed.libA || libraryIDs[1] != seed.libB {
		t.Fatalf("unapplied queue libraries = %v, want [%d %d] (every library, granted or not)", libraryIDs, seed.libA, seed.libB)
	}

	// ONE apply pass stamps every slot's row — the cutoff predicate carries no
	// user scoping, so nothing survives unlearned.
	if err := s.ApplyTagWeights(ctx, []string{"genre.drama"}, t1); err != nil {
		t.Fatalf("ApplyTagWeights: %v", err)
	}
	itemIDs, _, _, _, err = s.ListUnappliedWatched(ctx)
	if err != nil {
		t.Fatalf("ListUnappliedWatched (post-apply): %v", err)
	}
	if itemIDs == nil || len(itemIDs) != 0 {
		t.Fatalf("unapplied queue after apply = %#v, want non-nil empty (both slots stamped)", itemIDs)
	}
}
